using System;
using UnityEngine;
using FiresCore.Logging;

namespace FiresDiscordIntegration
{
    // FiresDiscordIntegration's console banners, rendered through the shared
    // FiresCore Banner engine.
    //
    //   PrintBig()  → chat bubble struck by a lightning bolt with the FIRES
    //                 DISCORD brand. Fires at the very top of Awake as the
    //                 load announcement.
    //   Print()     → compact bubble + bolt over a relay-status frame
    //                 ("RELAY LINKED"). Fires once when ZNetScene is ready.
    //
    // Art generated by Tools\gen_fires_banner.ps1 (spec: FiresDiscordIntegration).
    // Color zones: bubble outline (Blue/DarkBlue), lightning bolt (Cyan/DarkCyan),
    // brand (White/Blue), base (DarkGray).
    internal static class FiresDiscordBanner
    {
        private static bool s_compactPrinted;

        public static void PrintBig()
        {
            try
            {
                EmitHeader("Fires Discord Integration Loading...");
                Banner.Print(ToSegments(s_bigLines));
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresDiscordIntegration] Big banner failed: {ex.Message}");
            }
        }

        public static void Print()
        {
            if (s_compactPrinted) return;
            s_compactPrinted = true;
            try
            {
                EmitHeader("Fires Discord Integration Loaded.");
                Banner.Print(s_compactLines);
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresDiscordIntegration] Compact banner failed: {ex.Message}");
            }
        }

        // Routes the one-line header through the plugin's BepInEx log source (not
        // Debug.Log) so it prints once, colored by FiresLogColorPatch via the
        // Fires source name, without a raw white stdout duplicate.
        private static void EmitHeader(string text)
        {
            if (FiresDiscordIntegrationPlugin.Log != null) FiresDiscordIntegrationPlugin.Log.LogInfo(text);
            else Debug.Log($"[FiresDiscordIntegration] {text}");
        }

        private static Banner.Segment[][] ToSegments((string text, ConsoleColor color)[] lines)
        {
            var result = new Banner.Segment[lines.Length][];
            for (int i = 0; i < lines.Length; i++)
                result[i] = new[] { new Banner.Segment(lines[i].text, lines[i].color) };
            return result;
        }

        // Compact banner — chat bubble with a lightning bolt over a relay-status
        // frame. 31-char frame body (3 lead + ╔ + 26 ═ + ╗); 📡 is a surrogate pair, but the console
        // ADVANCES ONE column for it (no VS16), however wide the font paints the glyph, so this row pads it as one cell.
