            new[]
            {
                new Banner.Segment("         │    ",       ConsoleColor.Blue),
                new Banner.Segment("/",                    ConsoleColor.Cyan),
                new Banner.Segment("     │",               ConsoleColor.Blue),
            },
            new[] { new Banner.Segment("         ╰──╮  ╭────╯",          ConsoleColor.Blue) },
            new[] { new Banner.Segment("             ╰╯",                ConsoleColor.DarkBlue) },
            new[] { new Banner.Segment("   ╔══════════════════════════╗", ConsoleColor.DarkGray) },
            new[]
            {
                new Banner.Segment("   ║   ",              ConsoleColor.DarkGray),
                new Banner.Segment("[",                    ConsoleColor.Gray),
                new Banner.Segment("██████████████████",   ConsoleColor.Green),
                new Banner.Segment("]",                    ConsoleColor.Gray),
                new Banner.Segment("   ║",                 ConsoleColor.DarkGray),
            },
            new[]
            {
                new Banner.Segment("   ║     ",            ConsoleColor.DarkGray),
                new Banner.Segment("📡 RELAY LINKED",      ConsoleColor.Cyan),
                new Banner.Segment("       ║",              ConsoleColor.DarkGray),
            },
            new[] { new Banner.Segment("   ╚══════════════════════════╝", ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("    FIRES DISCORD INTEGRATION",  ConsoleColor.Cyan) },
            new Banner.Segment[0],
            new[] { new Banner.Segment("   Fires Discord Integration Loaded", ConsoleColor.Magenta) },
        };

